def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Identify separator rows and columns (all cells are 6)
    sep_rows = [i for i in range(rows) if all(grid[i][j] == 6 for j in range(cols))]
    sep_cols = [j for j in range(cols) if all(grid[i][j] == 6 for i in range(rows))]

    # Group rows into bands
    band_rows = []
    curr = []
    for r in range(rows):
        is_sep = all(grid[r][c] == 6 for c in range(cols))
        if is_sep:
            if curr: band_rows.append(curr)
            curr = []
        else:
            curr.append(r)
    if curr: band_rows.append(curr)

    # Group columns into bands
    band_cols = []
    curr = []
